import {buildClient} from 'webcommander-sdk';

const client = await buildClient();

const response = await client.adminCustomers.getCustomers({limit: 20, status: 'active'});
for (const customer of response.map.customers) {
    console.log(customer.customer_id, customer.email);
}

use WebCommander\Sdk\Client\ClientRegistry;
use WebCommander\Sdk\Resources\Customers\AdminCustomers;

$client = ClientRegistry::buildClient();

$response = AdminCustomers::getCustomers($client, ['limit' => 20, 'status' => 'active']);

foreach ($response->map['customers'] as $customer) {
    echo $customer['customer_id'], ' ', $customer['email'], PHP_EOL;
}

import com.webcommander.sdk.client.ApiResponse;
import com.webcommander.sdk.client.ClientRegistry;
import com.webcommander.sdk.client.WebCommanderClient;
import java.util.List;
import java.util.Map;

WebCommanderClient client = ClientRegistry.buildClient();

ApiResponse response = client.adminCustomers().getCustomers(Map.of("limit", 20, "status", "active"));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("customers")) {
    Map<?, ?> customer = (Map<?, ?>) row;
    System.out.println(customer.get("customer_id") + " " + customer.get("email"));
}

using WebCommander.Sdk.Client;

await using var client = WebCommanderClient.BuildClient();

var response = await client.AdminCustomers.GetCustomersAsync(
    new Dictionary<string, object?> { ["limit"] = 20, ["status"] = "active" });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var customer in ((IReadOnlyList<object?>)body["customers"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{customer["customer_id"]} {customer["email"]}");

import 'package:webcommander_sdk/webcommander_sdk.dart';

final client = buildClient();

final response = await client.adminCustomers.getCustomers(
    queryParams: {'limit': 20, 'status': 'active'});
for (final customer in (response.map as Map)['customers'] as List) {
  print('${(customer as Map)['customer_id']} ${customer['email']}');
}

import (
	"context"
	"fmt"
	"log"

	wc "bitbucket.org/webalive/webcommander-sdk-go/v3"
)

ctx := context.Background()
client, err := wc.BuildClient(nil)
if err != nil {
	log.Fatal(err)
}
defer client.Close()

resp, err := client.AdminCustomers().GetCustomers(ctx, map[string]any{"limit": 20, "status": "active"}, nil)
if err != nil {
	log.Fatal(err)
}
for _, row := range resp.Map().(map[string]any)["customers"].([]any) {
	customer := row.(map[string]any)
	fmt.Println(customer["customer_id"], customer["email"])
}

