import com.webcommander.sdk.client.ApiResponse;
import com.webcommander.sdk.client.ClientRegistry;
import com.webcommander.sdk.client.WebCommanderClient;
import java.util.Map;

WebCommanderClient client = ClientRegistry.buildClient();

ApiResponse response = client.adminCustomers().createCustomer(Map.of("customer", Map.of(
        "first_name", "Jane", "last_name", "Doe", "email", "jane@example.com", "company", false)));
Map<?, ?> customer = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("customer");
System.out.println(customer.get("customer_id"));

using WebCommander.Sdk.Client;

await using var client = WebCommanderClient.BuildClient();

var response = await client.AdminCustomers.CreateCustomerAsync(new Dictionary<string, object?>
{
