import com.webcommander.sdk.client.ApiResponse;
import com.webcommander.sdk.client.ClientRegistry;
import com.webcommander.sdk.client.WebCommanderClient;
import java.util.Map;

WebCommanderClient client = ClientRegistry.buildClient();

ApiResponse response = client.shippingMethods().setShippingMethodDefault(2);
Map<?, ?> shippingMethod = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("shipping_method");
System.out.println(shippingMethod.get("name") + " " + shippingMethod.get("is_default"));

using WebCommander.Sdk.Client;

await using var client = WebCommanderClient.BuildClient();

var response = await client.ShippingMethods.SetShippingMethodDefaultAsync(2);
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var shippingMethod = (IReadOnlyDictionary<string, object?>)body["shipping_method"]!;
Console.WriteLine($"{shippingMethod["name"]} {shippingMethod["is_default"]}");

import 'package:webcommander_sdk/webcommander_sdk.dart';

final client = buildClient();

final response = await client.shippingMethods.setShippingMethodDefault(2);
final shippingMethod = (response.map as Map)['shipping_method'] as Map;
print('${shippingMethod['name']} ${shippingMethod['is_default']}');

import (
	"context"
	"fmt"
	"log"

	wc "bitbucket.org/webalive/webcommander-sdk-go/v3"
)

ctx := context.Background()
client, err := wc.BuildClient(nil)
